{
  "table": {
    "name": "postHistory",
    "purpose": "One row per post-history event on a Stack Exchange-style Q&A site — the standard 'PostHistory' table of a Stack Exchange data dump (sibling tables posts, users, comments, votes, badges, tags, postLinks; content such as tags '<regression>', '<r>', '<probability>' and the moderator 'whuber' indicate the site is Cross Validated, stats.stackexchange.com). Each row records a single event in a post's life: initial title/body/tags at creation, later edits and rollbacks, closure, deletion, migration, etc. The rows sharing a PostId, grouped by RevisionGUID, reconstruct a post's full revision and moderation history."
  },
  "columns": {
    "Comment": {
      "role": "free_text",
      "name": "Comment",
      "description": "Free-text revision comment / edit summary attached to the event; empty string (181,184 rows, ~60%) means no comment. Values are either auto-generated by the site's edit UI ('edited title', 'edited tags', 'edited body', 'added 1 characters in body', 'removed signature and greetings'), suggested-edit audit lines ('Proposed by 26080 approved by 21054, -1 edit id of 3592'), or free-form reasons typed by editors ('presentation needed improvement!').",
      "status": "resolved"
    },
    "CreationDate": {
      "role": "date",
      "name": "CreationDate",
      "description": "Timestamp (YYYY-MM-DD HH:MM:SS) when the history event occurred, spanning 2009-02-02 (site launch) to 2014-09-14 (dump date). Tight clusters such as 81 rows at 2012-02-22 19:46:04 reflect bulk/batched operations (e.g. a mass retag or data backfill) rather than individual user actions.",
      "status": "resolved"
    },
    "Id": {
      "role": "identifier",
      "name": "Id",
      "description": "Primary key of postHistory: unique identifier (1–386,848) of one history-event row. The 'referenced_by' joins reported for it (comments.PostId, posts.ParentId, posts.PostTypeId, postLinks.LinkTypeId, votes.VoteTypeId) are numeric coincidences — those columns point at posts.Id or small type codes, not at this table.",
      "status": "resolved"
    },
    "PostHistoryTypeId": {
      "role": "code",
      "name": "PostHistoryTypeId",
      "description": "Code identifying the kind of history event (Stack Exchange's PostHistoryTypeId); 25 distinct codes in the range 1–38. Corroborated mapping: 1=Initial Title, 2=Initial Body, 3=Initial Tags, 4=Edit Title, 5=Edit Body, 6=Edit Tags, 7/8/9=Rollback Title/Body/Tags, 10=Post Closed, 11=Post Reopened, 12=Post Deleted, 13=Post Undeleted, 14/15=Post Locked/Unlocked, 16=Community Owned; codes 17–38 cover migration, merging, protection, post notices, tweeting/mentioning and spam/offensive/flag events per the standard Stack Exchange list (exact labels for these rarer codes are not independently verifiable from this table alone). Evidence: type 2 occurs 91,974 times vs 91,976 distinct PostIds (every post has exactly one initial-body row); types 1 (42,909) and 3 (42,921) match the number of questions — the only posts with title/tags; type 5 is the most frequent edit, matching the 'edited body' comments; close events carry a JSON voter list in Text. The reported join to posts.Id is spurious — these are small type codes, not post ids.",
      "status": "resolved"
    },
    "PostId": {
      "role": "foreign_key",
      "name": "PostId",
      "description": "Id of the post this event applies to (references posts.Id). 91,976 distinct posts with up to 32 events each; the rows sharing a PostId form that post's history. The reported join to comments.Id is a numeric coincidence.",
      "status": "resolved"
    },
    "RevisionGUID": {
      "role": "identifier",
      "name": "RevisionGUID",
      "description": "UUID grouping the history rows that belong to one logical revision: a question's creation writes three rows (initial title, body, tags) sharing one GUID, and a single edit touching title+body+tags likewise shares one GUID — hence only 193,951 distinct GUIDs for 303,155 rows (uniqueness 0.64). The all-zero GUID (169 rows) is a placeholder for events that are not revisions (e.g. close/reopen/lock).",
      "status": "resolved"
    },
    "Text": {
      "role": "free_text",
      "name": "Text",
      "description": "The content written by the event: the title text for title events, the body markdown for body events, the tag string for tag events (e.g. '<regression><r>', '<probability>', '<reference-request>'), and a JSON record of the close/reopen voters for moderation events (e.g. '{\"Voters\":[{\"Id\":919,\"DisplayName\":\"whuber\"}]}'). Empty string (24,482 rows) for events that carry no content (lock, protect, migrate, etc.).",
      "status": "resolved"
    },
    "UserDisplayName": {
      "role": "free_text",
      "name": "UserDisplayName",
      "description": "Display name of the user who caused the event, populated only when the account cannot be referenced through UserId (deleted or never-registered users) — hence the anonymized 'userNNNNN' forms; empty string in 298,316 of 303,155 rows.",
      "status": "resolved"
    },
    "UserId": {
      "role": "foreign_key",
      "name": "UserId",
      "description": "Id of the user who performed the event (references users.Id). -1 (the minimum) is the Community/system account in Stack Exchange dumps; NULL in ~7% of rows when the acting user is unknown or deleted, in which case UserDisplayName may carry the name instead. The most frequent ids (7290, 919, 805, 88, 930) are the site's most active editors; 919 is the moderator 'whuber' (see the voter JSON in Text).",
      "status": "resolved"
    }
  }
}
